-- 1) Allow the app to write budgets (currently read-only)
DROP POLICY IF EXISTS "public_all" ON budgets;
CREATE POLICY "public_all" ON budgets FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

-- 2) Seed/refresh the 2026 "Budget Prévisionnel" values from the Excel file
ON CONFLICT (site_id, date) DO UPDATE SET target = EXCLUDED.target;

-- 3) Backfill sales.target for already-synced days so the chart updates immediately
UPDATE sales s SET target = b.target
FROM budgets b
WHERE s.site_id = b.site_id AND s.date = b.date AND s.period = '''day''';
